  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "A related ionizable tropane carboxylate showed no significant brain uptake in rats, demonstrating that zwitterionic/ionizable scaffolds can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A zwitterionic 99mTc-labeled compound had brain/blood ratios of only 0.04–0.10 in rats, directly showing that zwitterionic character and high binding can prevent meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Enalapril, a carboxylate/amine-containing drug, produced only low brain and CSF levels after acute dosing in rats, supporting poor CNS access for similar ionizable molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ramiprilat, a zwitterionic ACE inhibitor, had a free CSF/plasma ratio of about 0.02 in dogs, indicating very slow blood-brain barrier crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DiPOA, an ionizable opioid with a brain-to-plasma ratio of 0.019, demonstrates that extremely low CNS penetration can abolish systemic CNS efficacy.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A basic, polar radiotracer showed poor brain uptake that increased dramatically after ABC transporter inhibition, indicating efflux liability at the BBB that is plausible for the query's ionizable amine/acid features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is fexofenadine, a zwitterionic molecule with a carboxylic acid and basic piperidine. All high-transfer experimental analogues show poor brain/CSF penetration, low brain-to-plasma ratios, or efflux-mediated exclusion, and the physicochemical prior also predicts low passive permeability and high efflux. Therefore meaningful CNS access is unlikely.",
  "evidence_gaps": [
